"use strict";
const KEY="starfall-command-v1";
const BUILDINGS={mine:{name:"Metal Mine",base:80,rate:12,desc:"Extracts metal from the crust."},crystal:{name:"Crystal Refinery",base:95,rate:8,desc:"Refines rare crystals."},deuterium:{name:"Deuterium Synthesizer",base:120,rate:5,desc:"Produces high-energy fuel."},solar:{name:"Solar Array",base:110,rate:15,desc:"Increases energy production."},shipyard:{name:"Shipyard",base:220,rate:0,desc:"Unlocks ship construction."},lab:{name:"Research Lab",base:180,rate:0,desc:"Unlocks scientific advances."}};
const TECH={weapons:{name:"Weapons Systems",cost:[200,140,70],desc:"Increases fleet combat power."},engines:{name:"Propulsion",cost:[150,180,90],desc:"Improves fleet speed and strength."},economy:{name:"Extraction Optimization",cost:[180,220,100],desc:"Boosts resource production."}};
const SHIPS={fighter:{name:"Interceptor",cost:[120,55,20],power:14,require:1},frigate:{name:"Frigate",cost:[330,180,90],power:45,require:2},cruiser:{name:"Cruiser",cost:[800,450,260],power:125,require:3}};
const defaultState=()=>({name:"New Horizon",turn:1,res:{metal:500,crystal:350,deuterium:180},build:{mine:1,crystal:1,deuterium:1,solar:1,shipyard:0,lab:0},tech:{weapons:0,engines:0,economy:0},ships:{fighter:3,frigate:0,cruiser:0},enemy:0,log:["Your colony has been established. Welcome, Commander."]});
let state;try{state=Object.assign(defaultState(),JSON.parse(localStorage.getItem(KEY)||"null")||{});if(!state.res||!state.build||!state.tech||!state.ships)throw Error()}catch{state=defaultState()}
let tab="overview";const $=id=>document.getElementById(id),fmt=n=>Math.floor(n).toLocaleString("en-US");
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function note(s){state.log.unshift("Turn "+state.turn+": "+s);state.log=state.log.slice(0,35)}
function production(){let b=state.build,e=state.tech.economy;return {metal:10+b.mine*12*(1+e*.12),crystal:6+b.crystal*8*(1+e*.12),deuterium:3+b.deuterium*5*(1+e*.12)}}
function energy(){let b=state.build;return b.solar*25-(b.mine+b.crystal+b.deuterium)*6}
function can(cost){return ["metal","crystal","deuterium"].every((r,i)=>state.res[r]>=cost[i])}
function pay(cost){["metal","crystal","deuterium"].forEach((r,i)=>state.res[r]-=cost[i])}
function costs(cost){return cost.map((v,i)=>fmt(v)+" "+["M","C","D"][i]).join(" · ")}
function buildingCost(id){let n=state.build[id];return [Math.ceil(BUILDINGS[id].base*Math.pow(1.55,n)),Math.ceil(BUILDINGS[id].base*.55*Math.pow(1.55,n)),Math.ceil(BUILDINGS[id].base*.2*Math.pow(1.55,n))]}
function action(type,id){if(type==="build"){let c=buildingCost(id);if(!can(c))return;pay(c);state.build[id]++;note("Upgraded "+BUILDINGS[id].name+" to level "+state.build[id])}else if(type==="research"){if(!state.build.lab)return;let c=TECH[id].cost.map(x=>Math.ceil(x*Math.pow(1.8,state.tech[id])));if(!can(c))return;pay(c);state.tech[id]++;note("Researched "+TECH[id].name+" level "+state.tech[id])}else if(type==="ship"){if(state.build.shipyard<SHIPS[id].require)return;let c=SHIPS[id].cost;if(!can(c))return;pay(c);state.ships[id]++;note("Constructed one "+SHIPS[id].name)}else if(type==="tick"){let p=production(),factor=energy()<0?.5:1;for(let r of Object.keys(p))state.res[r]+=Math.floor(p[r]*factor);state.turn++;note("Production collected"+(factor<1?" (energy shortage: 50%)":""))}else if(type==="battle"){let power=Object.keys(SHIPS).reduce((s,k)=>s+state.ships[k]*SHIPS[k].power,0)*(1+state.tech.weapons*.2+state.tech.engines*.05);let threat=35+state.enemy*22;if(power<=0)return;let won=power>=threat;let losses=Math.min(state.ships.fighter,Math.ceil(threat/35));state.ships.fighter-=losses;if(won){state.enemy++;state.res.metal+=130+state.enemy*30;state.res.crystal+=70+state.enemy*20;note("Victory at sector "+state.enemy+"! Salvage recovered. Lost "+losses+" interceptors.")}else{note("Raid repelled. Lost "+losses+" interceptors. Build a stronger fleet.")}}else if(type==="reset"){if(!confirm("Erase local practice progress?"))return;state=defaultState()}save();render()}
function card(title,desc,meta,button){return '<article class="card"><h3>'+title+'</h3><p>'+desc+'</p><div class="stat">'+meta+'</div>'+button+'</article>'}
function btn(label,fn,disabled=false){return '<button '+(disabled?'disabled':'')+' onclick="'+fn+'">'+label+'</button>'}
function render(){let p=production();$("resources").innerHTML=Object.entries(state.res).map(([k,v])=>'<div class="resource"><small>'+k.toUpperCase()+'</small><strong>'+fmt(v)+'</strong></div>').join("");let tabs={overview:"Command",buildings:"Buildings",research:"Research",fleet:"Shipyard",combat:"Combat",intel:"Intel & Log"};$("nav").innerHTML=Object.entries(tabs).map(([k,v])=>'<button class="'+(tab===k?'active':'')+'" onclick="navigate(\''+k+'\')">'+v+'</button>').join("");let h="";
if(tab==="overview")h='<section class="hero"><span class="tag">SECTOR 7 • TURN '+state.turn+'</span><h2>'+state.name+'</h2><p>Establish an economy, research technology, build a fleet and clear hostile sectors.</p>'+btn("Advance one turn","action('tick')")+'</section><div class="grid">'+card("Production per turn","Resources are awarded when advancing turns.","Metal +"+fmt(p.metal)+" · Crystal +"+fmt(p.crystal)+" · Deuterium +"+fmt(p.deuterium),"")+card("Power Grid","Negative energy halves resource output.",energy()+' net energy',"")+card("Defense Fleet","Your current fleet strength.",fmt(Object.entries(SHIPS).reduce((n,[k,s])=>n+state.ships[k]*s.power,0))+" base power","")+card("Frontier Progress","Hostile sectors defeated.",state.enemy+" sectors secured",btn("Open combat","navigate('combat')"))+'</div>';
if(tab==="buildings")h='<h2>Planetary Infrastructure</h2><div class="grid">'+Object.entries(BUILDINGS).map(([id,b])=>{let c=buildingCost(id);return card(b.name,b.desc,"Level "+state.build[id]+" · "+costs(c),btn("Upgrade","action('build','"+id+"')",!can(c)))}).join("")+'</div>';
if(tab==="research")h='<h2>Research Division</h2><p class="muted">Requires a Research Lab.</p><div class="grid">'+Object.entries(TECH).map(([id,t])=>{let c=t.cost.map(x=>Math.ceil(x*Math.pow(1.8,state.tech[id])));return card(t.name,t.desc,"Level "+state.tech[id]+" · "+costs(c),btn("Research","action('research','"+id+"')",!state.build.lab||!can(c)))}).join("")+'</div>';
if(tab==="fleet")h='<h2>Orbital Shipyard</h2><p class="muted">Upgrade the Shipyard to unlock larger hulls.</p><div class="grid">'+Object.entries(SHIPS).map(([id,s])=>card(s.name,"Combat power "+s.power+" · Requires Shipyard "+s.require,"Owned "+state.ships[id]+" · "+costs(s.cost),btn("Construct","action('ship','"+id+"')",state.build.shipyard<s.require||!can(s.cost)))).join("")+'</div>';
if(tab==="combat")h='<section class="hero"><h2>Frontier Operations</h2><p>Engage the next hostile sector. Enemy strength rises after each victory. Battles resolve instantly in this practice build.</p><p>Estimated enemy power: <strong>'+(35+state.enemy*22)+'</strong></p>'+btn("Launch raid","action('battle')",Object.values(state.ships).every(v=>v===0))+'</section>';
if(tab==="intel")h='<h2>Command Log</h2><div class="card log">'+state.log.map(s=>'<p>'+s+'</p>').join("")+'</div><p>'+btn("Reset practice universe","action('reset')")+'</p>';
$("content").innerHTML=h}
function navigate(t){tab=t;render()}window.navigate=navigate;window.action=action;render();
